import{c as t,Q as s,j as e,m as n}from"./chunks/framework.DOi4mjdC.js";const p="/assets/zh-cn_formulaimage_0000002516303034.BIH1e3Ie.png",h=JSON.parse('{"title":"Compares（灵活标量位置）","description":"","frontmatter":{},"headers":[{"level":1,"title":"Compares（灵活标量位置）","slug":"compares灵活标量位置"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/基础API/Memory矢量计算/比较与选择/Compares（灵活标量位置）.md","filePath":"api/SIMD-API/基础API/Memory矢量计算/比较与选择/Compares（灵活标量位置）.md"}'),l={name:"api/SIMD-API/基础API/Memory矢量计算/比较与选择/Compares（灵活标量位置）.md"};function r(i,a,o,c,d,m){return s(),e("div",null,[...a[0]||(a[0]=[n('<h1 id="compares-灵活标量位置" tabindex="-1">Compares（灵活标量位置） <a class="header-anchor" href="#compares-灵活标量位置" aria-label="Permalink to &quot;Compares（灵活标量位置）&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>x</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>x</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>提供灵活标量位置的接口，支持标量在前和标量在后两种场景。其中标量输入支持配置LocalTensor单点元素，计算公式如下，idx表示LocalTensor单点元素的位置系数。</p><p><img src="'+p+`" alt=""></p><p>支持多种比较模式：</p><ul><li><p>LT：小于（less than）</p></li><li><p>GT：大于（greater than）</p></li><li><p>GE：大于或等于（greater than or equal to）</p></li><li><p>EQ：等于（equal to）</p></li><li><p>NE：不等于（not equal to）</p></li><li><p>LE：小于或等于（less than or equal to）</p></li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><ul><li><p>tensor前n个数据计算</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T0 = BinaryDefaultType, typename T1 = BinaryDefaultType, bool isSetMask = true, const BinaryConfig &amp;config = DEFAULT_BINARY_CONFIG, typename T2, typename T3, typename T4&gt;</span></span>
<span class="line"><span>__aicore__ inline void Compares(const T2&amp; dst, const T3&amp; src0, const T4&amp; src1, CMPMODE cmpMode, uint32_t count)</span></span></code></pre></div></li><li><p>tensor高维切分计算</p><ul><li><p>mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T0 = BinaryDefaultType, typename T1 = BinaryDefaultType, bool isSetMask = true, const BinaryConfig &amp;config = DEFAULT_BINARY_CONFIG, typename T2, typename T3, typename T4&gt;</span></span>
<span class="line"><span>__aicore__ inline void Compares(const T2&amp; dst, const T3&amp; src0, const T4&amp; src1, CMPMODE cmpMode, const uint64_t mask[], uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li><li><p>mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;typename T0 = BinaryDefaultType, typename T1 = BinaryDefaultType, bool isSetMask = true, const BinaryConfig &amp;config = DEFAULT_BINARY_CONFIG, typename T2, typename T3, typename T4&gt;</span></span>
<span class="line"><span>__aicore__ inline void Compares(const T2&amp; dst, const T3&amp; src0, const T4&amp; src1, CMPMODE cmpMode, const uint64_t mask, uint8_t repeatTime, const UnaryRepeatParams&amp; repeatParams)</span></span></code></pre></div></li></ul></li></ul><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 模板参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T0</td><td>对于固定标量位置接口，表示源操作数数据类型。 特别地，对于灵活标量位置接口，为预留参数，暂未启用，为后续的功能扩展做保留，需要指定时，传入默认值BinaryDefaultType即可。</td></tr><tr><td>T1</td><td>对于固定标量位置接口，表示目的操作数数据类型。 特别地，对于灵活标量位置接口，为预留参数，暂未启用，为后续的功能扩展做保留，需要指定时，传入默认值BinaryDefaultType即可。</td></tr><tr><td>isSetMask</td><td>是否在接口内部设置mask。 true，表示在接口内部设置mask。false，表示在接口外部设置mask，开发者需要使用SetVectorMask接口设置mask值。这种模式下，接口入参中的mask值设置为占位符MASK_PLACEHOLDER，用于占位，无实际含义。</td></tr><tr><td>config</td><td>类型为BinaryConfig，当标量为LocalTensor单点元素类型时生效，用于指定单点元素操作数位置。默认值DEFAULT_BINARY_CONFIG，表示右操作数为标量。 &lt;pre class=&quot;screen&quot; codetype=&quot;Cpp&quot; id=&quot;screen13143195284213&quot;&gt;struct BinaryConfig { int8_t scalarTensorIndex = 1; // 用于指定标量为LocalTensor单点元素时标量的位置，0表示左操作数，1表示右操作数 }; constexpr BinaryConfig DEFAULT_BINARY_CONFIG = {1};&lt;/pre&gt;</td></tr><tr><td>T2</td><td>LocalTensor类型，根据输入参数dst自动推导相应的数据类型，开发者无需配置该参数，保证dst满足数据类型的约束即可。</td></tr><tr><td>T3</td><td>LocalTensor类型或标量类型，根据输入参数src0自动推导相应的数据类型，开发者无需配置该参数，保证src0满足数据类型的约束即可。</td></tr><tr><td>T4</td><td>LocalTensor类型或标量类型，根据输入参数src1自动推导相应的数据类型，开发者无需配置该参数，保证src1满足数据类型的约束即可。</td></tr></tbody></table><p><strong>表 2</strong> 接口参数说明</p><table tabindex="0"><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。 类型为LocalTensor，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 dst用于存储比较结果，将dst中uint8_t类型的数据按照bit位展开，由左至右依次表征对应位置的src0和src1的比较结果，如果比较后的结果为真，则对应比特位为1，否则为0。 Ascend 950PR/Ascend 950DT，支持的数据类型为：uint8_t</td></tr><tr><td>src0/src1</td><td>输入</td><td>灵活标量位置接口中源操作数。 类型为LocalTensor时，支持当作矢量操作数或标量单点元素，支持的TPosition为VECIN/VECCALC/VECOUT。 LocalTensor的起始地址需要32字节对齐。 Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t/uint8_t/int16_t/uint16_t/half/bfloat16_t/float/int32_t/uint32_t/int64_t/uint64_t/double（double只支持CMPMODE::EQ） 类型为标量时： Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t/uint8_t/int16_t/uint16_t/half/bfloat16_t/float/int32_t/uint32_t/int64_t/uint64_t/double（double只支持CMPMODE::EQ） 数据类型需要与目的操作数保持一致。</td></tr><tr><td>cmpMode</td><td>输入</td><td>CMPMODE类型，表示比较模式，包括EQ，NE，GE，LE，GT，LT。 LT:src0小于（less than）src1GT:src0大于（greater than）src1GE：src0大于或等于（greater than or equal to）src1EQ：src0等于（equal to）src1NE：src0不等于（not equal to）src1LE：src0小于或等于（less than or equal to）src1</td></tr><tr><td>mask/mask[]</td><td>输入</td><td>mask用于控制每次迭代内参与计算的元素。 连续模式：表示前面连续的多少个元素参与计算。取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask∈[1, 128]；当操作数为32位时，mask∈[1, 64]。 逐bit模式：可以按位控制哪些元素参与计算，bit位的值为1表示参与计算，0表示不参与。参数类型为长度为2或者4的uint64_t类型数组。 例如，mask=[8, 0]，8=0b1000，表示仅第4个元素参与计算。 参数取值范围和操作数的数据类型有关，数据类型不同，每次迭代内能够处理的元素个数最大值不同。当操作数为16位时，mask[0]、mask[1]∈[0, 264-1]并且不同时为0；当操作数为32位时，mask[1]为0，mask[0]∈(0, 264-1]。</td></tr><tr><td>repeatTime</td><td>输入</td><td>重复迭代次数。矢量计算单元，每次读取连续的256Bytes数据进行计算，为完成对输入数据的处理，必须通过多次迭代（repeat）才能完成所有数据的读取与计算。repeatTime表示迭代的次数。 关于该参数的具体描述请参考高维切分API。</td></tr><tr><td>repeatParams</td><td>输入</td><td>控制操作数地址步长的参数。UnaryRepeatParams类型，包含操作数相邻迭代间相同DataBlock的地址步长，操作数同一迭代内不同DataBlock的地址步长等参数。 相邻迭代间的地址步长参数说明请参考repeatStride；同一迭代内DataBlock的地址步长参数说明请参考dataBlockStride。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。设置count时，需要保证count个元素所占空间256字节对齐。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</p></li><li><p>调用灵活标量位置接口且源操作数为LocalTensor单点元素的场景，不支持源操作数和目的操作数地址重叠。</p></li><li><p>dst按照小端顺序排序成二进制结果，对应src中相应位置的数据比较结果。</p></li><li><p><strong>使用tensor前n个数据参与计算的接口，设置count时，需要保证count个元素所占空间256字节对齐。</strong></p></li><li><p>针对Ascend 950PR/Ascend 950DT，int8_t/uint8_t/uint64_t/int64_t/double数据类型仅支持tensor前n个数据计算接口，double只支持CMPMODE::EQ。</p></li><li><p>左操作数及右操作数中，必须有一个为矢量；当前不支持左右操作数同时为标量。</p></li><li><p>本接口传入LocalTensor单点数据作为标量时，idx参数需要传入编译期已知的常量，传入变量时需要声明为constexpr。</p></li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><p>对于灵活标量位置接口，支持直接传入立即数或单点LocalTensor作为标量，并且支持标量在前和在后两种调用方式。</p><p>完整的调用样例可参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/02_features/03_basic_api/02_memory_vector_compute/compare" target="_blank" rel="noreferrer">Compare类样例</a>场景四。</p><ul><li><p>tensor前n个数据计算接口样例</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 标量在后，src1Local[0]作为标量</span></span>
<span class="line"><span>AscendC::Compares(dstLocal, src0Local, src1Local[0], AscendC::CMPMODE::LT, srcDataSize);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 标量在前，src0Local[0]作为标量</span></span>
<span class="line"><span>static constexpr AscendC::BinaryConfig config = { 0 };</span></span>
<span class="line"><span>AscendC::Compares&lt;BinaryDefaultType, BinaryDefaultType, true, config&gt;(dstLocal, src0Local[0], src1Local, AscendC::CMPMODE::LT, srcDataSize);</span></span></code></pre></div></li><li><p>tensor高维切分计算-mask连续模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask = 256 / sizeof(float); // 256为每个迭代处理的字节数</span></span>
<span class="line"><span>int repeat = 4;</span></span>
<span class="line"><span>AscendC::UnaryRepeatParams repeatParams = { 1, 1, 8, 8 };</span></span>
<span class="line"><span>// repeat = 4, 64 elements one repeat, 256 elements total</span></span>
<span class="line"><span>// dstBlkStride, srcBlkStride = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>// 标量在后，src1Local[0]作为标量</span></span>
<span class="line"><span>AscendC::Compares(dstLocal, src0Local, src1Local[0], AscendC::CMPMODE::LT, mask, repeat, repeatParams);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 标量在前，src0Local[0]作为标量</span></span>
<span class="line"><span>static constexpr AscendC::BinaryConfig config = { 0 };</span></span>
<span class="line"><span>AscendC::Compares&lt;BinaryDefaultType, BinaryDefaultType, true, config&gt;(dstLocal, src0Local[0], src1Local, AscendC::CMPMODE::LT, mask, repeat, repeatParams);</span></span></code></pre></div></li><li><p>tensor高维切分计算-mask逐bit模式</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>uint64_t mask[2] = { UINT64_MAX, 0};</span></span>
<span class="line"><span>int repeat = 4;</span></span>
<span class="line"><span>AscendC::UnaryRepeatParams repeatParams = { 1, 1, 8, 8 };</span></span>
<span class="line"><span>// repeat = 4, 64 elements one repeat, 256 elements total</span></span>
<span class="line"><span>// srcBlkStride, = 1, no gap between blocks in one repeat</span></span>
<span class="line"><span>// dstRepStride, srcRepStride = 8, no gap between repeats</span></span>
<span class="line"><span>// 标量在后，src1Local[0]作为标量</span></span>
<span class="line"><span>AscendC::Compares(dstLocal, src0Local, src1Local[0], AscendC::CMPMODE::LT, mask, repeat, repeatParams);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 标量在前，src0Local[0]作为标量</span></span>
<span class="line"><span>static constexpr AscendC::BinaryConfig config = { 0 };</span></span>
<span class="line"><span>AscendC::Compares&lt;BinaryDefaultType, BinaryDefaultType, true, config&gt;(dstLocal, src0Local[0], src1Local, AscendC::CMPMODE::LT, mask, repeat, repeatParams);</span></span></code></pre></div></li></ul>`,23)])])}const _=t(l,[["render",r]]);export{h as __pageData,_ as default};
